fn accent(s: i32) -> i32 {
    match s {
        0 => 0xff4040,
        1 => 0x40ff70,
        2 => 0x4080ff,
        _ => 0xffcc30,
    }
}

fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut sel: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 && px >= 40 && px < 220 && py >= 80 && py < 240 {
        sel = (py - 80) / 40;
        host::display::state_set(0, sel);
    }
    host::display::state_set(1, down);
    host::display::clear(0x101010);
    host::display::draw_string(40, 40, "PICK AN ACCENT", 0x808080, 1);
    let mut i: i32 = 0;
    while i < 4 {
        let y: i32 = 80 + i * 40;
        host::display::fill_rect(40, y + 4, 22, 22, 0x404040);
        host::display::fill_rect(43, y + 7, 16, 16, 0x101010);
        if i == sel {
            host::display::fill_rect(46, y + 10, 10, 10, accent(sel));
        }
        i = i + 1;
    }
    host::display::draw_string(74, 88, "CRIMSON", 0xffffff, 1);
    host::display::draw_string(74, 128, "MINT", 0xffffff, 1);
    host::display::draw_string(74, 168, "AZURE", 0xffffff, 1);
    host::display::draw_string(74, 208, "GOLD", 0xffffff, 1);
    host::display::fill_rect(260, 80, 60, 156, accent(sel));
    host::display::present();
}
